function validate([nodes, parent, value]) {
  if (!Number.isInteger(nodes) || nodes < 1 || nodes > 10000) return 'nodes is a whole number from 1 to 10^4.';
  if (!Array.isArray(parent) || parent.length !== nodes) return 'parent needs exactly nodes entries.';
  if (!Array.isArray(value) || value.length !== nodes) return 'value needs exactly nodes entries.';
  if (parent[0] !== -1) return 'parent[0] must be -1: node 0 is the root.';
  for (let i = 1; i < nodes; i++) {
    if (!Number.isInteger(parent[i]) || parent[i] < 0 || parent[i] >= nodes || parent[i] === i) return `parent[${i}] must be another node's label.`;
  }
  if (value.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each value is a whole number from -10^5 to 10^5.';
  // Every node must be reachable from the root, which also rules out cycles.
  const children = Array.from({ length: nodes }, () => []);
  for (let i = 1; i < nodes; i++) children[parent[i]].push(i);
  const queue = [0];
  for (let k = 0; k < queue.length; k++) for (const child of children[queue[k]]) queue.push(child);
  if (queue.length !== nodes) return 'parent must form one tree rooted at node 0 (no cycles).';
  return null;
}

