function deleteTreeNodes(nodes, parent, value) {
  // Give each node's value to itself and every ancestor, then keep a node only if no ancestor (or itself) sums to 0.
  const total = new Array(nodes).fill(0);
  for (let u = 0; u < nodes; u++) {
    for (let a = u; a !== -1; a = parent[a]) total[a] += value[u];
  }
  let kept = 0;
  for (let u = 0; u < nodes; u++) {
    let alive = true;
    for (let a = u; a !== -1; a = parent[a]) if (total[a] === 0) alive = false;
    if (alive) kept++;
  }
  return kept;
}

