function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const nodes = size === 'large' ? 2000 : 1 + pick(9);
  // Shuffle the labels 1..nodes-1 so parents are not always smaller than their children.
  const labels = Array.from({ length: nodes - 1 }, (_, i) => i + 1);
  for (let i = labels.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [labels[i], labels[j]] = [labels[j], labels[i]];
  }
  const created = [0, ...labels];
  const shape = rand();
  const parent = new Array(nodes).fill(-1);
  for (let k = 1; k < nodes; k++) {
    const j = shape < 0.2 ? k - 1 : shape < 0.35 ? 0 : pick(k);
    parent[created[k]] = created[j];
  }
  const limit = size === 'large' && rand() < 0.5 ? 100000 : rand() < 0.5 ? 3 : 50;
  const value = Array.from({ length: nodes }, () => pick(2 * limit + 1) - limit);
  // Turn some subtrees into zero-sum ones: children come after their parent in creation order.
  const childSum = new Array(nodes).fill(0);
  const chance = rand() * 0.4;
  for (let k = nodes - 1; k >= 0; k--) {
    const node = created[k];
    if (rand() < chance && Math.abs(childSum[node]) <= 100000) value[node] = -childSum[node];
    if (k > 0) childSum[parent[node]] += value[node] + childSum[node];
  }
  return [nodes, parent, value];
}
